package com.yuegang.zhihui.ai.application;
import static org.assertj.core.api.Assertions.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.ai.domain.RetrievalGateway;import com.yuegang.zhihui.ai.infrastructure.CommerceToolGateway;import com.yuegang.zhihui.common.test.YghTestContainerFactory;import com.yuegang.zhihui.search.api.SearchHit;import java.util.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.datasource.DriverManagerDataSource;
class AiEvaluationBranchesTest{@Test void evaluatesExpectedRefusalAndForbiddenAnswers(){try(var mysql=YghTestContainerFactory.mysql().start()){Flyway.configure().dataSource(mysql.jdbcUrl(),mysql.username(),mysql.credential()).locations("classpath:db/migration").load().migrate();var ds=new DriverManagerDataSource(mysql.jdbcUrl(),mysql.username(),mysql.credential());var governance=new AiGovernanceService(ds);governance.addCase(new SaveEvaluationCaseRequest("CUSTOMS","无资料的通关政策","资料",null,true,true),9);governance.addCase(new SaveEvaluationCaseRequest("TRACEABILITY","溯源是什么","资料","回答",false,true),9);RetrievalGateway retrieval=(q,c,l)->q.contains("无资料")?List.of():List.of(new SearchHit("1","2","title","evidence",1,1,2));var tools=new CommerceToolGateway("http://localhost:1","http://localhost:1","01234567890123456789012345678901".getBytes(),new ObjectMapper());var chat=new ChatService(retrieval,(s,u)->"回答",tools,ds);var results=new AiEvaluationService(ds,chat).run(7);assertThat(results).hasSize(2);assertThat(results).filteredOn(EvaluationRunView::passed).singleElement().satisfies(x->assertThat(x.score()).isEqualTo(100));assertThat(results).filteredOn(x->!x.passed()).singleElement().satisfies(x->assertThat(x.failureReason()).isEqualTo("FORBIDDEN_ANSWER_MATCHED"));}}}
